import{_ as s,a0 as i,w as c,s as l,ao as o,I as r,x as a,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux中安装Cisco Packet Tracer | LCTT x X-CMD","titleTemplate":false,"description":"Linux中安装Cisco Packet Tracer | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中安装Cisco Packet Tracer | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中安装Cisco Packet Tracer | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150126 Installing Cisco Packet tracer in Linux","title":"Linux中安装Cisco Packet Tracer","tag":"201506","desc":""},"relativePath":"201506/20150126 Installing Cisco Packet tracer in Linux.md","filePath":"[post].md"}'),d={name:"201506/20150126 Installing Cisco Packet tracer in Linux.md"};function u(k,t,g,m,P,T){const e=i("Link");return c(),l("div",null,[t[20]||(t[20]=o(`<h1 id="linux中安装cisco-packet-tracer" tabindex="-1">Linux中安装Cisco Packet Tracer <a class="header-anchor" href="#linux中安装cisco-packet-tracer" aria-label="Permalink to “Linux中安装Cisco Packet Tracer”">​</a></h1><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/Main_picture.png" alt=""></p><h3 id="cisco-packet-tracer是什么" tabindex="-1">Cisco Packet tracer是什么？ <a class="header-anchor" href="#cisco-packet-tracer是什么" aria-label="Permalink to “Cisco Packet tracer是什么？”">​</a></h3><p><strong>Cisco Packet Tracer</strong>是一个强大的网络模拟工具，用于进行Cisco认证时的培训。它为我们提供了各个路由器和网络设备的良好的接口视图，这些模拟设备带有很多选项，跟使用物理机一样，我们可以在网络中使用无限的设备。我们能在单个工程中创建多个网络，以获得专业化的训练。Packet Tracer将提供给我们模拟的应用层协议，如<strong>HTTP</strong>，<strong>DNS</strong>，以及像<strong>RIP</strong>，<strong>OSPF</strong>，<strong>EIGRP</strong>等路由协议。</p><p>现在，它发布了包含有<strong>ASA 5505防火墙</strong>命令行配置的版本。Packet Tracer通常用于Windows版本，但没有Linux版本。这里，我们可以下载并安装Cisco Packet Tracer。</p><h4 id="新发布的cisco-packet-tracer版本" tabindex="-1">新发布的Cisco Packet Tracer版本： <a class="header-anchor" href="#新发布的cisco-packet-tracer版本" aria-label="Permalink to “新发布的Cisco Packet Tracer版本：”">​</a></h4><p>下一代Cisco Packet Tracer版本将会是Cisco Packet Tracer 6.2，当前还处于开发中。</p><h3 id="我的环境设置" tabindex="-1">我的环境设置： <a class="header-anchor" href="#我的环境设置" aria-label="Permalink to “我的环境设置：”">​</a></h3><p><strong>主机名</strong> : desktop1.unixmen.com</p><p><strong>IP地址</strong> : 192.168.0.167</p><p><strong>操作系统</strong> : Ubuntu 14.04 LTS Desktop</p><pre><code># hostname

# ifconfig | grep inet

# lsb_release -a
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_001.png" alt=""></p><h3 id="步骤-1-首先-我们需要下载cisco-packet-tracer。" tabindex="-1">步骤 1： 首先，我们需要下载Cisco Packet Tracer。 <a class="header-anchor" href="#步骤-1-首先-我们需要下载cisco-packet-tracer。" aria-label="Permalink to “步骤 1： 首先，我们需要下载Cisco Packet Tracer。”">​</a></h3><p>要从官方网站下载Packet Tracer，我们需要持有一个令牌，登入Cisco NetSpace，然后从Offering菜单选择CCNA &gt; Cisco Packet Tracer来开始下载。如果我们没有令牌，可以从下面的链接中获得，我已经将它上传到了Droppox。</p>`,15)),r("p",null,[t[1]||(t[1]=a("官方站点： ",-1)),n(e,{href:"https://www.netacad.com/"},{default:p(()=>[...t[0]||(t[0]=[a("https://www.netacad.com/",-1)])]),_:1})]),t[21]||(t[21]=r("p",null,"大多数人没有下载Packet Tracer的令牌，出于该原因，我已经将它上传到了dropbox，你可以从下面的URL获得Packet Tracer。",-1)),r("p",null,[n(e,{href:"https://www.dropbox.com/s/5evz8gyqqvq3o3v/Cisco%20Packet%20Tracer%206.1.1%20Linux.tar.gz?dl=0"},{default:p(()=>[...t[2]||(t[2]=[a("下载Cisco Packet Tracer 6.1.1",-1)])]),_:1})]),t[22]||(t[22]=r("p",null,[r("img",{src:"http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_002.png",alt:""})],-1)),t[23]||(t[23]=r("h3",{id:"步骤-2-安装java",tabindex:"-1"},[a("步骤 2： 安装Java： "),r("a",{class:"header-anchor",href:"#步骤-2-安装java","aria-label":"Permalink to “步骤 2： 安装Java：”"},"​")],-1)),t[24]||(t[24]=r("p",null,"要安装Packet Tracer，我们需要安装java。我们可以使用默认的仓库安装java；或者添加PPA仓库，然后更新包缓存来安装java。",-1)),t[25]||(t[25]=r("p",null,"使用以下命令来安装默认的jre",-1)),t[26]||(t[26]=r("pre",null,[r("code",null,`    # sudo apt-get install default-jre
`)],-1)),t[27]||(t[27]=r("p",null,[r("img",{src:"http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_003.png",alt:""})],-1)),t[28]||(t[28]=r("p",null,"（或者）",-1)),t[29]||(t[29]=r("p",null,"使用下面的步骤来安装Java Run-time并设置环境。",-1)),r("p",null,[t[4]||(t[4]=a("从官方站点下载Java：",-1)),n(e,{href:"http://www.oracle.com/technetwork/java/javase/downloads/jre8-downloads-2133155.html"},{default:p(()=>[...t[3]||(t[3]=[a("下载Java",-1)])]),_:1})]),t[30]||(t[30]=o(`<pre><code># tar -zxvf jre-8u31-linux-x64.tar.gz
# sudo mkdir -p /usr/lib/jvm
# sudo mv -v jre1.8.0_31 /usr/lib/jvm/
# cd /usr/lib/jvm/
# sudo update-alternatives --install &quot;/usr/bin/java&quot; &quot;java&quot; &quot;/usr/lib/jvm/jre1.8.0_31/bin/java&quot; 1
# sudo update-alternatives --set &quot;java&quot; &quot;/usr/lib/jvm/jre1.8.0_31/bin/java&quot;
</code></pre><p>通过编辑用户参数文件来设置Java环境，并添加路径相关的参数。当我们添加进用户参数文件后，我们机器上的每个用户都可以用java了。</p><pre><code># sudo vi /etc/profile
</code></pre><p>将以下条目添加到/etc/profile文件中：</p><pre><code>export JAVA_HOME=/usr/lib/jvm/jre1.8.0_31
export PATH=$PATH:/usr/java/jre1.8.0_31/bin
</code></pre><p>运行以下命令来立即激活java路径。</p><pre><code># . /etc/profile
</code></pre><p>检查Java版本和环境：</p><pre><code># echo $JAVA_HOME
# java -version
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_004.png" alt=""></p><h3 id="步骤-3-启用32位架构支持" tabindex="-1">步骤 3： 启用32位架构支持： <a class="header-anchor" href="#步骤-3-启用32位架构支持" aria-label="Permalink to “步骤 3： 启用32位架构支持：”">​</a></h3><p>对于Packet Tracer，我们需要一些32位包。要安装32位包，我们需要使用以下命令来安装一些依赖。</p><pre><code># sudo dpkg --add-architecture i386
# sudo apt-get update
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_005.png" alt=""></p><pre><code># sudo apt-get install libc6:i386
# sudo apt-get install lib32z1 lib32ncurses5 lib32bz2-1.0
# sudo apt-get install libnss3-1d:i386 libqt4-qt3support:i386 libssl1.0.0:i386 libqtwebkit4:i386 libqt4-scripttools:i386
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_006.png" alt=""></p><h3 id="步骤-4-解压并安装软件包" tabindex="-1">步骤 4： 解压并安装软件包： <a class="header-anchor" href="#步骤-4-解压并安装软件包" aria-label="Permalink to “步骤 4： 解压并安装软件包：”">​</a></h3><p>使用tar命令来解压下载的包。</p><pre><code># mv Cisco\\ Packet\\ Tracer\\ 6.1.1\\ Linux.tar.gz\\?dl\\=0 Cisco_Packet_tracer.tar.gz

# tar -zxvf Cisco_Packet_tracer.tar.gz
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_007.png" alt=""></p><p>导航到解压后的目录</p><pre><code># cd PacketTracer611Student
</code></pre><p>现在，该开始安装了。安装过程很简单，只需几秒钟即可搞定。</p><pre><code># sudo ./install
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_008.png" alt=""></p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_009.png" alt=""></p><p>要使用Packet Tracer工作，我们需要设置环境，Cisco已经提供了环境脚本，我们需要以root用户来运行该脚本以设置环境变量。</p><pre><code># sudo ./set_ptenv.sh
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_010.png" alt=""></p><p>安装到此结束。接下来，我们需要为Packet Tracer创建桌面图标。</p><p>通过创建下面的桌面文件来创建桌面图标。</p><pre><code># sudo su
# cd /usr/share/applications
# sudo vim packettracer.desktop
</code></pre><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_011.png" alt=""></p><p>使用vim编辑器或你喜爱的那个编辑器来添加以下内容到文件。</p><pre><code>[Desktop Entry]
 Name= Packettracer
 Comment=Networking
 GenericName=Cisco Packettracer
 Exec=/opt/packettracer/packettracer
 Icon=/usr/share/icons/packettracer.jpeg
 StartupNotify=true
 Terminal=false
 Type=Application
</code></pre><p>使用wq!来保存并退出vim。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_012.png" alt=""></p><h3 id="步骤-5-运行packet-tracer" tabindex="-1">步骤 5： 运行Packet Tracer <a class="header-anchor" href="#步骤-5-运行packet-tracer" aria-label="Permalink to “步骤 5： 运行Packet Tracer”">​</a></h3><pre><code># sudo packettracer
</code></pre><p>好了，我们已经成功将Packet Tracer安装到Linux中。上述安装步骤适用于所有基于Debian的Linux发行版。</p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_013.png" alt=""></p><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/01/pkt_014.png" alt=""></p><h3 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to “资源”">​</a></h3>`,43)),r("p",null,[t[6]||(t[6]=a("主页：",-1)),n(e,{href:"https://www.netacad.com/"},{default:p(()=>[...t[5]||(t[5]=[a("Netacad",-1)])]),_:1})]),t[31]||(t[31]=r("h3",{id:"尾声",tabindex:"-1"},[a("尾声： "),r("a",{class:"header-anchor",href:"#尾声","aria-label":"Permalink to “尾声：”"},"​")],-1)),t[32]||(t[32]=r("p",null,"这里，我们展示了如何安装Packet Tracer到Linux发行版中。希望你们找到了将你们所钟爱的模拟器安装到Linux中的方法。",-1)),t[33]||(t[33]=r("hr",null,null,-1)),r("p",null,[t[8]||(t[8]=a("via: ",-1)),n(e,{href:"http://www.unixmen.com/installing-cisco-packet-tracer-linux/"},{default:p(()=>[...t[7]||(t[7]=[a("http://www.unixmen.com/installing-cisco-packet-tracer-linux/",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=a("作者：",-1)),n(e,{href:"http://www.unixmen.com/author/babin/"},{default:p(()=>[...t[9]||(t[9]=[a("babin",-1)])]),_:1}),t[13]||(t[13]=a(" 译者：",-1)),n(e,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[10]||(t[10]=[a("GOLinux",-1)])]),_:1}),t[14]||(t[14]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[a("wxy",-1)])]),_:1})]),r("p",null,[t[17]||(t[17]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[a("LCTT",-1)])]),_:1}),t[18]||(t[18]=a(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[a("Linux中国",-1)])]),_:1}),t[19]||(t[19]=a(" 荣誉推出",-1))])])}const C=s(d,[["render",u]]);export{f as __pageData,C as default};
